metadata.er-schema:
{
  "title": "looply · 营销活动（促销折扣）实体关系图",
  "version": "v1.6 · 2026-07-27",
  "tables": [
    {
      "name": "promotion",
      "comment": "营销活动",
      "columns": [
        {
          "name": "id",
          "comment": "活动ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "promotion_name",
          "comment": "活动名称",
          "constraint": ""
        },
        {
          "name": "market_id",
          "comment": "所属市场(建活动第一步选定,创建后不可改)",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "status",
          "comment": "状态 draft/active/ended",
          "constraint": ""
        },
        {
          "name": "start_at",
          "comment": "活动开始时间",
          "constraint": ""
        },
        {
          "name": "end_at",
          "comment": "活动结束时间（空=长期）",
          "constraint": ""
        },
        {
          "name": "created_by",
          "comment": "创建人",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "活动=分组容器,与市场 1:1(A6 拍板):所有配置在所属市场币种/时区下表达;起止时间按所属市场本地时区判定;跨市场同策略=复制活动到目标市场"
    },
    {
      "name": "promotion_rule",
      "comment": "折扣规则",
      "columns": [
        {
          "name": "id",
          "comment": "规则ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "promotion_id",
          "comment": "所属活动",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "rule_name",
          "comment": "规则名称（订单侧快照来源）",
          "constraint": ""
        },
        {
          "name": "trigger_type",
          "comment": "触发方式 auto自动/code优惠码",
          "constraint": ""
        },
        {
          "name": "discount_type",
          "comment": "折扣类型 product商品/order订单",
          "constraint": ""
        },
        {
          "name": "value_type",
          "comment": "折扣值类型 percentage百分比/fixed固定金额",
          "constraint": ""
        },
        {
          "name": "percentage_value",
          "comment": "百分比值（value_type=percentage用）",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种（随所属市场，下列金额字段录值口径）",
          "constraint": ""
        },
        {
          "name": "fixed_amount",
          "comment": "固定金额折扣值（value_type=fixed用，按所属市场币种）",
          "constraint": ""
        },
        {
          "name": "max_discount_amount",
          "comment": "最大优惠封顶（percentage用，空=不封顶）",
          "constraint": ""
        },
        {
          "name": "product_scope",
          "comment": "商品范围 all/category/brand/listing（仅商品折扣）",
          "constraint": ""
        },
        {
          "name": "min_type",
          "comment": "门槛类型 none无/amount满额/quantity满件",
          "constraint": ""
        },
        {
          "name": "min_quantity",
          "comment": "满件门槛值（min_type=quantity用）",
          "constraint": ""
        },
        {
          "name": "min_amount",
          "comment": "满额门槛值（min_type=amount用，按所属市场币种）",
          "constraint": ""
        },
        {
          "name": "max_item_count",
          "comment": "每单最多作用件数（商品折扣可选封顶）",
          "constraint": ""
        },
        {
          "name": "total_usage_limit",
          "comment": "总使用次数上限（空=不限）",
          "constraint": ""
        },
        {
          "name": "per_user_limit",
          "comment": "每人使用次数上限（空=不限）",
          "constraint": ""
        },
        {
          "name": "used_count",
          "comment": "已核销次数（冗余计数，用尽即停）",
          "constraint": ""
        },
        {
          "name": "can_combine",
          "comment": "是否可与其他折扣叠加 默认否（D4；V2演进为combines_with类别模型）",
          "constraint": ""
        },
        {
          "name": "eligibility",
          "comment": "适用人群 all全部【人群定向V2预留】",
          "constraint": ""
        },
        {
          "name": "budget_total",
          "comment": "规则预算总额【V2预留】",
          "constraint": ""
        },
        {
          "name": "budget_spent",
          "comment": "已消耗预算【V2预留】",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态 active/paused",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "聚合根。规则真正载体；trigger_type=auto无码/code绑码；金额预算池/人群定向为V2预留"
    },
    {
      "name": "promotion_target",
      "comment": "规则商品范围明细",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "rule_id",
          "comment": "规则ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "target_type",
          "comment": "圈选类型 category品类/brand品牌/listing指定商品",
          "constraint": ""
        },
        {
          "name": "target_id",
          "comment": "目标ID（对应category_id/brand_id/listing_id）",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        }
      ],
      "note": "仅商品折扣使用；product_scope=all 时无记录。圈选不随商品售出/下架删除，下单时按商品实时可售状态动态判定（A5）"
    },
    {
      "name": "promotion_code",
      "comment": "优惠码",
      "columns": [
        {
          "name": "id",
          "comment": "优惠码ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "rule_id",
          "comment": "规则ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "code",
          "comment": "优惠码字符串（全局唯一，不同活动不可用同一码）",
          "constraint": "UNIQUE"
        },
        {
          "name": "market_id",
          "comment": "所属市场（冗余自活动，结算查码后校验买家市场一致）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "status",
          "comment": "状态 active/disabled",
          "constraint": ""
        },
        {
          "name": "used_count",
          "comment": "该码已使用次数（冗余计数）",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        }
      ],
      "note": "仅 trigger_type=code 使用；一规则可多码做定向发放；code 全局唯一,checkout 按码直接查,再校验活动所属市场=买家市场"
    },
    {
      "name": "promotion_redemption",
      "comment": "核销流水",
      "columns": [
        {
          "name": "id",
          "comment": "核销ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "rule_id",
          "comment": "规则ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "code_id",
          "comment": "优惠码ID（自动折扣为空）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "user_id",
          "comment": "用户ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "order_id",
          "comment": "订单ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "status",
          "comment": "状态 valid有效/reverted已回滚",
          "constraint": ""
        },
        {
          "name": "redeemed_at",
          "comment": "核销时间",
          "constraint": ""
        },
        {
          "name": "reverted_at",
          "comment": "回滚时间（整单退款触发，空=未回滚）",
          "constraint": ""
        }
      ],
      "note": "仅计数不记金额。(rule_id,order_id)组合唯一+原子扣减防并发超发（A2）；限次只数status=valid；整单退款事件→reverted并释放限次（D3）"
    },
    {
      "name": "promotion_price_alert",
      "comment": "到手价告警",
      "columns": [
        {
          "name": "id",
          "comment": "告警ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "listing_id",
          "comment": "商品ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "market_id",
          "comment": "市场ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "original_price",
          "comment": "商品原价（触发时快照，按市场币种）",
          "constraint": ""
        },
        {
          "name": "final_price",
          "comment": "到手价（触发时快照）",
          "constraint": ""
        },
        {
          "name": "alert_type",
          "comment": "告警类型 cumulative累计超阈/sudden_drop环比突变",
          "constraint": ""
        },
        {
          "name": "drop_pct",
          "comment": "累计降幅百分比（相对原价）",
          "constraint": ""
        },
        {
          "name": "prev_final_price",
          "comment": "上一次扫描到手价（环比告警用，累计告警可空）",
          "constraint": ""
        },
        {
          "name": "change_pct",
          "comment": "环比降幅百分比（相对上次到手价）",
          "constraint": ""
        },
        {
          "name": "threshold_pct",
          "comment": "触发时阈值快照（对应类型的阈值）",
          "constraint": ""
        },
        {
          "name": "calc_snapshot",
          "comment": "价格计算链路快照（逐步规则/减免额，排查依据）",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态 pending待处理/resolved已处理/ignored已忽略",
          "constraint": ""
        },
        {
          "name": "handle_action",
          "comment": "处置动作 pause_promotion暂停活动/manual人工调整/none",
          "constraint": ""
        },
        {
          "name": "handle_note",
          "comment": "处置备注",
          "constraint": ""
        },
        {
          "name": "handled_by",
          "comment": "处置人",
          "constraint": ""
        },
        {
          "name": "handled_at",
          "comment": "处置时间",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "告警时间",
          "constraint": ""
        }
      ],
      "note": "事中防线工作台：双阈值监控——累计降幅(相对原价,默认50%)+环比降幅(相对上次扫描到手价,默认20%),均为全局系统配置项不建表；到手价基线由监控服务内部维护(不建业务表)；命中规则以链路快照留证"
    },
    {
      "name": "ref_product",
      "comment": "商品域（引用）",
      "columns": [
        {
          "name": "listing_id",
          "comment": "在售商品ID",
          "constraint": ""
        },
        {
          "name": "spu_id",
          "comment": "SPU ID",
          "constraint": ""
        },
        {
          "name": "category_id",
          "comment": "品类ID",
          "constraint": ""
        },
        {
          "name": "brand_id",
          "comment": "品牌ID",
          "constraint": ""
        },
        {
          "name": "listing_status",
          "comment": "在售状态（下单时实时判定可享，A5）",
          "constraint": ""
        }
      ],
      "note": "圈选活动商品时只读；商品折扣命中维度"
    },
    {
      "name": "ref_market",
      "comment": "market（引用）",
      "columns": [
        {
          "name": "market_id",
          "comment": "市场ID",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种",
          "constraint": ""
        }
      ],
      "note": "活动所属市场、币种与本地时区口径来源"
    },
    {
      "name": "ref_user",
      "comment": "用户（引用）",
      "columns": [
        {
          "name": "user_id",
          "comment": "用户ID",
          "constraint": ""
        }
      ],
      "note": "核销归属用户，每人限次判定"
    },
    {
      "name": "ref_order",
      "comment": "订单-优惠记录（引用）",
      "columns": [
        {
          "name": "order_id",
          "comment": "订单ID",
          "constraint": ""
        },
        {
          "name": "promotion_ref_id",
          "comment": "促销规则ID（指向rule）",
          "constraint": ""
        },
        {
          "name": "discount_amount",
          "comment": "优惠金额（营销计算，订单落库）",
          "constraint": ""
        }
      ],
      "note": "order_discount.promotion_ref_id → promotion_rule.id；分摊金额由营销域计算，订单落地存储"
    }
  ],
  "relations": [
    {
      "from": "promotion_rule",
      "to": "promotion",
      "type": "N:1",
      "label": "归属活动",
      "penwidth": 1.6
    },
    {
      "from": "promotion",
      "to": "ref_market",
      "type": "N:1",
      "label": "所属市场",
      "penwidth": 1.4
    },
    {
      "from": "promotion_target",
      "to": "promotion_rule",
      "type": "N:1",
      "label": "圈选商品"
    },
    {
      "from": "promotion_code",
      "to": "promotion_rule",
      "type": "N:1",
      "label": "优惠码",
      "penwidth": 1.4
    },
    {
      "from": "promotion_code",
      "to": "ref_market",
      "type": "N:1",
      "label": "市场校验(冗余)",
      "color": "#9AA0A6",
      "style": "dashed"
    },
    {
      "from": "promotion_redemption",
      "to": "promotion_rule",
      "type": "N:1",
      "label": "核销",
      "penwidth": 1.4
    },
    {
      "from": "promotion_redemption",
      "to": "promotion_code",
      "type": "N:1",
      "label": "码核销"
    },
    {
      "from": "promotion_target",
      "to": "ref_product",
      "type": "N:1",
      "label": "引用",
      "color": "#9AA0A6",
      "style": "dashed"
    },
    {
      "from": "promotion_redemption",
      "to": "ref_user",
      "type": "N:1",
      "label": "引用",
      "color": "#9AA0A6",
      "style": "dashed"
    },
    {
      "from": "promotion_redemption",
      "to": "ref_order",
      "type": "N:1",
      "label": "引用",
      "color": "#9AA0A6",
      "style": "dashed"
    },
    {
      "from": "ref_order",
      "to": "promotion_rule",
      "type": "N:1",
      "label": "规则快照引用",
      "color": "#9AA0A6",
      "style": "dashed"
    },
    {
      "from": "promotion_price_alert",
      "to": "ref_product",
      "type": "N:1",
      "label": "告警商品",
      "color": "#C0392B",
      "penwidth": 1.2
    },
    {
      "from": "promotion_price_alert",
      "to": "ref_market",
      "type": "N:1",
      "label": "引用",
      "color": "#9AA0A6",
      "style": "dashed"
    },
    {
      "from": "promotion_price_alert",
      "to": "promotion_rule",
      "type": "N:N",
      "label": "命中规则(链路快照)",
      "color": "#9AA0A6",
      "style": "dashed"
    }
  ],
  "design_rules": {
    "活动-规则-码三层": "活动=分组容器；折扣规则=规则真正载体(聚合根)；优惠码=有码触发凭证。一活动多规则、一规则多码",
    "触发方式": "promotion_rule.trigger_type=auto时无码自动生效；=code时挂1~N个promotion_code由用户输码触发",
    "分摊职责": "营销域负责优惠分摊规则定义与行级分摊计算(随试算供给)；订单域负责订单金额计算与分摊数据落地存储 order_discount(域边界 2026-07-26 修正)",
    "订单侧契约": "order_discount.promotion_ref_id 指向 promotion_rule.id，promotion_name 存 rule_name 快照",
    "活动市场1比1": "A6(2026-07-27 拍板):一个活动只属一个市场,建活动第一步选定且创建后不可改;所有金额字段在 rule 层按所属市场币种录值;跨市场同策略=复制活动到目标市场;汇率模块仅作录值换算参考,不自动生效",
    "用量控制": "总次数看 rule.used_count、每人次数看(rule_id,user_id)计数、码级看 code_id、有效期看活动 start_at/end_at",
    "状态分层": "活动容器 promotion.status=draft/active/ended(生命周期);熔断态落规则层 promotion_rule.status=active/paused(监控一键暂停写入点);1:1 模型下运营视角活动状态=两层合成展示,分层保留 V2 多规则演进空间",
    "码唯一性": "code 全局唯一(UK):不同活动不可用同一优惠码,含不同市场也不可重复;checkout 按码直接定位活动,再校验活动市场=买家当前市场,不一致则不适用",
    "叠加口径_V1": "can_combine=false 的规则同单命中取优惠最大一条；=true 的按顺序作用(百分比基于逐步折后价、固定金额累减)；实付兜底(≥0)由订单计算引擎统一夹逼(A2/D4)",
    "退款回滚": "订单整单退款事件驱动 redemption.status valid→reverted + reverted_at；used_count-1、每人限次释放；部分退款不回滚不重算(D3)",
    "一品一件": "指定商品圈选关系不物理删除；下单按商品域实时可售状态动态判定，售出→暂不可享、退款回可售→自动恢复；全部不可售仅提醒运营不自动结束(A5)",
    "时区口径": "活动起止时间按所属市场本地时区判定(单市场化后无需配置,原 timezone_mode 废弃,D5 更新)",
    "资损监控_V1": "配置期价格试算拦截提醒(服务能力) + 到手价降幅监控(落 promotion_price_alert,独立优惠监控菜单工作台)；资损对账=日汇总核对 valid核销 vs order_discount(离线任务，报表化V2)",
    "优惠监控_V1": "双阈值监控:累计降幅阈值(相对原价,默认50%)+环比降幅阈值(相对上一次扫描到手价,默认20%),均为全局系统配置项(按活动/品类覆盖V2)；告警状态机 pending→resolved(记处置动作/人/备注)/ignored；同商品+同市场+同告警类型存在pending时更新不新增；处置含一键暂停命中活动；calc_snapshot 留存排查链路；到手价基线为监控服务内部数据不建业务表(2026-07-27 G3 反馈补充环比监控)",
    "优惠码方式": "手动输入+系统随机生成两种；手动码防猜校验(长度≥8、字母数字混合、禁纯连续序列)，规则落PRD不加字段(D6)",
    "V2预留": "budget_total/budget_spent(预算池)、阶梯门槛、eligibility(人群定向)、combines_with类别叠加模型、一人一码max_uses、活动维度聚合统计 均本版不落逻辑",
    "范围_V1": "仅平台运营创建；折扣成本默认平台承担；三方商家自主营销为后续版本"
  }
}
